def sieve_of_eratosthenes(n):
    """Return every prime number up to n."""
    flags = [True] * (n + 1)
    flags[0] = flags[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if flags[i]:
            for j in range(i * i, n + 1, i):
                flags[j] = False
    return [i for i, ok in enumerate(flags) if ok]

